// ════════════════════════════════════════════════════
// HIER DEINE WERTE EINTRAGEN:
// ════════════════════════════════════════════════════

const AUTH_KEY = 'SHELLY_AUTH_KEY_HIER_EINTRAGEN';
const SERVER   = 'https://shelly-175-eu.shelly.cloud';

// Geraete-IDs und Typen deiner 5 PV-Anlagen:
// Typen: 'pm1' = Shelly PM Mini, 'switch' = Shelly Plus Plug S
//        'em3' = Shelly Pro 3EM, 'em' = Shelly Pro EM-50
const GERAETE = [
    { id: 'd48afc481be0', typ: 'switch' },  // PV 1
    { id: '34b7da8ad1f4', typ: 'pm1'    },  // PV 2
    { id: 'ecda3bc15810', typ: 'pm1'    },  // PV 3
    { id: '5432046cd7a0', typ: 'pm1'    },  // PV 4
    { id: 'ecda3bc13404', typ: 'pm1'    },  // PV 5
];

// ════════════════════════════════════════════════════
// Ab hier nichts ändern
// ════════════════════════════════════════════════════

flow.set('pv_anzahl', GERAETE.length);

return GERAETE.map(g => ({
    url:     SERVER + '/device/status',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    payload: 'auth_key=' + AUTH_KEY + '&id=' + g.id,
    _typ:    g.typ,
    _id:     g.id,
}));

const typ    = msg._typ;
const antwort = msg.payload;

if (!antwort || !antwort.isok) {
    node.warn('Geraet ' + msg._id + ' nicht erreichbar');
    msg.payload = 0;
    return msg;
}

const s = antwort.data.device_status;
let watt = 0;

if (typ === 'pm1')    watt = (s['pm1:0']    || {}).apower          || 0;
if (typ === 'switch') watt = (s['switch:0'] || {}).apower          || 0;
if (typ === 'em3')    watt = (s['em:0']     || {}).total_act_power || 0;
if (typ === 'em')     watt = (s['em:0']     || {}).act_power       || 0;

msg.payload = Math.max(0, watt);
return msg;

const messungen = msg.payload;  // Array mit 5 Watt-Werten
const gesamt    = Math.round(messungen.reduce((s, w) => s + (w || 0), 0));

msg.payload = {
    'Ac/Power':      gesamt,
    'Ac/L1/Power':   gesamt,
    'Ac/L1/Voltage': 230.0,
    'Ac/L1/Current': parseFloat((gesamt / 230).toFixed(2)),
    'StatusCode':    7,
    'Connected':     1
};

node.status({
    fill:  gesamt > 0 ? 'green' : 'grey',
    shape: 'dot',
    text:  gesamt + ' W  (' + messungen.map(w => Math.round(w) + 'W').join(' + ') + ')'
});

return msg;
